// The note a pitched noise voice is level-matched at: constant-Q bands of white noise lose 3 dB
// per octave down, so a voice at `f` Hz is scaled by `sqrt(PITCH_REF_HZ / f)` — even across notes.
#define PITCH_REF_HZ 1000.0

// The envelope times' ranges in seconds (CE-R4.3; their normalized `0..1` is the seam's); sustain
// is a 0..1 level. `DECAY_MAX_S` is the ADSR's decay and the legacy `event` bell's ring alike
// (ADR 0054 P7). `pub` so the TUI units registry (ADR 0024) reports the same seconds the engine
// renders.
#define ATTACK_MAX_S 3.0

#define DECAY_MAX_S 4.0

#define RELEASE_MAX_S 4.0

// A gain's finite floor (`0` normalized) and its hard ceiling (ADR 0054 P1).
#define GAIN_FLOOR_DB -60.0

#define GAIN_CEILING_DB 6.0

// Default per-loop probability of a categorical move instead of a numeric drift step.
#define DEFAULT_CAT_CHANGE_PROB 0.15

// Built-in per-loop step cap `|δ|` (normalized `0..1`) when neither the runtime nor the loop doc
// authors one. Matches [`DitherConfig::default`].
#define DEFAULT_MAX_CHANGE 0.05

// Built-in **cumulative** drift half-width (normalized `0..1`): how far drift may move a param
// from its authored anchor over the whole session, when the loop doc omits `max_drift` (ADR 0025).
#define DEFAULT_MAX_DRIFT 0.15

// Max phase-modulation depth (radians) at `fm_index = 1`.
#define FM_INDEX_MAX 8.0

// Max osc-B detune (cents) at `osc_b_detune = 1`.
#define DETUNE_CENTS_MAX 50.0

// Dual-synth oversampling factor: osc + PM + drive run at `OVERSAMPLE×` the rate, then decimate
// through [`Aa2x`] (ADR 0009). 2× tames PM/drive sidebands that would otherwise fold.
#define OVERSAMPLE 2

